package Package4;

public class switchcasestatement2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int teamrank = 9;
		switch (teamrank) {
		case 1 : System.out.println("MI"); break;
		case 2 : System.out.println("GT"); break;
		case 3 : System.out.println("RCB"); break;
		case 4 : System.out.println("PBKS"); break;
		case 5 : System.out.println("DC"); break;
		case 6 : System.out.println("LSG"); break;
		case 7 : System.out.println("KKR"); break;
		case 8 : System.out.println("RR"); break;
		case 9 : System.out.println("SRH"); break;
		case 10 : System.out.println("CSK"); break;
		default : System.out.println("Invalid input"); break;
		}

	}

}
